window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-64499dfb95518e75"]={"versions": [{"id": "FIG-64499dfb95518e75", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Konzeptionelles Architektur- und Migrationsdiagramm auf Basis des AUTOSAR Classic Platform (CP) Schichtenmodells.\n</li><li><strong>Technischer Zweck:</strong> Veranschaulichung der Rückwärtskompatibilität (<em>Backward Compatibility</em>, BWC) standardisierter AUTOSAR-Applikationsschnittstellen (<em>Standardized Application Interfaces</em>). Es demonstriert die Koexistenz von Software-Komponenten (SWCs) unterschiedlicher Spezifikationsstände (R4.0.3 und R4.0.4) auf demselben Steuergerät (ECU) und derselben Basissoftware (BSW/RTE), ohne dass alle SWCs simultan hochgezogen oder refaktoriert werden müssen.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Ausführungsumgebung &amp; Schichten (ECU Core):</strong>\n<ul class=\"fig-list\"><li><code>Microcontroller</code>: Physikalische Hardware-Ebene.\n</li><li><code>Microcontroller Abstraction Layer (MCAL)</code>: Hardware-nahe Treiberschicht (z. B. Port, ADC, DIO, CAN).\n</li><li><code>ECU Abstraction Layer</code>: Abstraktion interner/externer Peripherie- und Transceiverbausteine.\n</li><li><code>Services Layer</code>: BSW-Basisdienste (System-, Speicher- und Kommunikationsstack inkl. ComM, EcuM, NvM, Dem, Det).\n</li><li><code>Complex Device Drivers (CDD)</code>: Bypass-Schicht zur Direktanbindung zeitkritischer oder nicht standardisierter Hardware an die RTE/Applikation.\n</li><li><code>Runtime Environment (RTE)</code>: Virtual Functional Bus (VFB) Instanziierung zur Entkopplung von Applikation und BSW sowie SWC-zu-SWC-Vermittlung.\n</li></ul>\n</li><li><strong>Applikationsschicht (SWC-Entitäten):</strong>\n<ul class=\"fig-list\"><li>Heterogene Menge von <code>ApplicationSwComponentType</code>-Instanzen: SWC_1, SWC_2, SWC_3, …, SWC_n-1, SWC_n.\n</li><li><strong>Versionsspezifische Ausprägung:</strong>\n<ul class=\"fig-list\"><li><em>Graue SWCs:</em> Verwenden standardisierte Schnittstellen gemäß Stand <strong>R4.0.3</strong>.\n</li><li><em>Orangefarbene SWCs:</em> Verwenden standardisierte Schnittstellen gemäß Stand <strong>R4.0.4</strong>.\n</li></ul>\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Kopplung:</strong>\n<ul class=\"fig-list\"><li>Port-basierte Kommunikation über <code>PortPrototype</code> (<code>PPortPrototype</code>, <code>RPortPrototype</code>, <code>PRPortPrototype</code>).\n</li><li>Die BWC-Beziehung (dargestellt durch den Transformationspfeil <code>BWC wrt std app if</code>) garantiert, dass die Schnittstellen-Verträge von R4.0.4 kompatible Obermengen oder semantisch identische Abbildungen von R4.0.3 sind, wodurch <code>AssemblySwConnector</code>-Verbindungen zwischen Komponenten unterschiedlicher Releasestände gültig bleiben.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<ul class=\"fig-list\"><li><strong>Migrations-/Evolutionsszenario (Statischer Systemzustand):</strong>\n<ul class=\"fig-list\"><li><em>Basiszustand (links):</em> Homogene Applikationsschicht; sämtliche Komponenten (SWC_1 bis SWC_n) basieren vollständig auf Schnittstellendefinitionen von R4.0.3.\n</li><li><em>Transitionszustand (rechts):</em> Inkrementelles Update einzelner Komponenten (SWC_2 und SWC_n-1) auf R4.0.4. Unveränderte Legacy-Komponenten (SWC_1, SWC_3, SWC_n) verbleiben auf R4.0.3-Standard-Interfaces.\n</li></ul>\n</li><li><strong>Laufzeitinteraktion:</strong>\n<ul class=\"fig-list\"><li>Datenaustausch (<code>Rte_Read</code>, <code>Rte_Write</code>) und Client/Server-Aufrufe (<code>Rte_Call</code>, <code>Rte_Result</code>) zwischen R4.0.3- und R4.0.4-SWCs werden transparent über den RTE-Code aufgelöst.\n</li><li>Es existieren keine dynamischen Fallbacks oder Laufzeit-Adapter; die Kompatibilität wird design- und generierungszeitlich durch identische Datentyplayouts, Skalierungen und Aufrufkonventionen sichergestellt.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative BWC-Vorgaben für Application Interfaces:</strong>\n<ul class=\"fig-list\"><li>Minor-/Bugfix-Releases standardisierter Applikationsschnittstellen (hier: R4.0.3 → R4.0.4) dürfen <strong>keine Breaking Changes</strong> enthalten:\n<ul class=\"fig-list\"><li>Keine Löschung oder Umbenennung bestehender <code>DataElement</code>s, <code>Operation</code>s oder Argumente.\n</li><li>Keine Änderung primitiver Datentypen, physikalischer Einheiten (CompuMethods) oder numerischer Skalierungsfaktoren.\n</li><li>Erweiterungen sind strikt additiv (z. B. neue optionale Record-Elemente, zusätzliche Fehlercodes).\n</li></ul>\n</li></ul>\n</li><li><strong>Auswirkungen auf Konfiguration und Tooling (ARXML &amp; RTE):</strong>\n<ul class=\"fig-list\"><li>Der RTE-Generator muss ARXML-Beschreibungen aus unterschiedlichen Release-Quellen auflösen können, ohne Typkollisionen bei systemweiten Standardtypen (z. B. <code>Std_ReturnType</code>, standardisierte Enums) zu erzeugen.\n</li><li>Integratoren müssen bei der Erstellung des <code>SystemExtract</code> sicherstellen, dass Port-Mappings zwischen SWCs verschiedener Releasestände formal typkompatibel deklariert sind.\n</li></ul>\n</li><li><strong>Entwicklungs- und Integrationspraxis:</strong>\n<ul class=\"fig-list\"><li><strong>Carry-over-Fähigkeit:</strong> Bereits abgenommene und qualifizierte Legacy-SWCs können ohne Quellcode- oder Schnittstellenanpassung in neuere Plattform-Projekte übernommen werden.\n</li><li><strong>Vermeidung von Re-Testing:</strong> Für unveränderte SWCs (R4.0.3) entfällt der Schnittstellen-Requalifizierungsaufwand; Tests können sich auf die geänderten Schnittstellenpfade der aktualisierten SWCs (R4.0.4) fokussieren.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-e8c38bcc09bf7986", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Konzeptionelles Architektur- und Migrationsdiagramm auf Basis des AUTOSAR Classic Platform (CP) Schichtenmodells.\n</li><li><strong>Technischer Zweck:</strong> Veranschaulichung der Rückwärtskompatibilität (<em>Backward Compatibility</em>, BWC) standardisierter AUTOSAR-Applikationsschnittstellen (<em>Standardized Application Interfaces</em>). Es demonstriert die Koexistenz von Software-Komponenten (SWCs) unterschiedlicher Spezifikationsstände (R4.0.3 und R4.0.4) auf demselben Steuergerät (ECU) und derselben Basissoftware (BSW/RTE), ohne dass alle SWCs simultan hochgezogen oder refaktoriert werden müssen.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Ausführungsumgebung &amp; Schichten (ECU Core):</strong>\n<ul class=\"fig-list\"><li><code>Microcontroller</code>: Physikalische Hardware-Ebene.\n</li><li><code>Microcontroller Abstraction Layer (MCAL)</code>: Hardware-nahe Treiberschicht (z. B. Port, ADC, DIO, CAN).\n</li><li><code>ECU Abstraction Layer</code>: Abstraktion interner/externer Peripherie- und Transceiverbausteine.\n</li><li><code>Services Layer</code>: BSW-Basisdienste (System-, Speicher- und Kommunikationsstack inkl. ComM, EcuM, NvM, Dem, Det).\n</li><li><code>Complex Device Drivers (CDD)</code>: Bypass-Schicht zur Direktanbindung zeitkritischer oder nicht standardisierter Hardware an die RTE/Applikation.\n</li><li><code>Runtime Environment (RTE)</code>: Virtual Functional Bus (VFB) Instanziierung zur Entkopplung von Applikation und BSW sowie SWC-zu-SWC-Vermittlung.\n</li></ul>\n</li><li><strong>Applikationsschicht (SWC-Entitäten):</strong>\n<ul class=\"fig-list\"><li>Heterogene Menge von <code>ApplicationSwComponentType</code>-Instanzen: SWC_1, SWC_2, SWC_3, …, SWC_n-1, SWC_n.\n</li><li><strong>Versionsspezifische Ausprägung:</strong>\n<ul class=\"fig-list\"><li><em>Graue SWCs:</em> Verwenden standardisierte Schnittstellen gemäß Stand <strong>R4.0.3</strong>.\n</li><li><em>Orangefarbene SWCs:</em> Verwenden standardisierte Schnittstellen gemäß Stand <strong>R4.0.4</strong>.\n</li></ul>\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Kopplung:</strong>\n<ul class=\"fig-list\"><li>Port-basierte Kommunikation über <code>PortPrototype</code> (<code>PPortPrototype</code>, <code>RPortPrototype</code>, <code>PRPortPrototype</code>).\n</li><li>Die BWC-Beziehung (dargestellt durch den Transformationspfeil <code>BWC wrt std app if</code>) garantiert, dass die Schnittstellen-Verträge von R4.0.4 kompatible Obermengen oder semantisch identische Abbildungen von R4.0.3 sind, wodurch <code>AssemblySwConnector</code>-Verbindungen zwischen Komponenten unterschiedlicher Releasestände gültig bleiben.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Migrations-/Evolutionsszenario (Statischer Systemzustand):</strong>\n<ul class=\"fig-list\"><li><em>Basiszustand (links):</em> Homogene Applikationsschicht; sämtliche Komponenten (SWC_1 bis SWC_n) basieren vollständig auf Schnittstellendefinitionen von R4.0.3.\n</li><li><em>Transitionszustand (rechts):</em> Inkrementelles Update einzelner Komponenten (SWC_2 und SWC_n-1) auf R4.0.4. Unveränderte Legacy-Komponenten (SWC_1, SWC_3, SWC_n) verbleiben auf R4.0.3-Standard-Interfaces.\n</li></ul>\n</li><li><strong>Laufzeitinteraktion:</strong>\n<ul class=\"fig-list\"><li>Datenaustausch (<code>Rte_Read</code>, <code>Rte_Write</code>) und Client/Server-Aufrufe (<code>Rte_Call</code>, <code>Rte_Result</code>) zwischen R4.0.3- und R4.0.4-SWCs werden transparent über den RTE-Code aufgelöst.\n</li><li>Es existieren keine dynamischen Fallbacks oder Laufzeit-Adapter; die Kompatibilität wird design- und generierungszeitlich durch identische Datentyplayouts, Skalierungen und Aufrufkonventionen sichergestellt.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative BWC-Vorgaben für Application Interfaces:</strong>\n<ul class=\"fig-list\"><li>Minor-/Bugfix-Releases standardisierter Applikationsschnittstellen (hier: R4.0.3 → R4.0.4) dürfen <strong>keine Breaking Changes</strong> enthalten:\n<ul class=\"fig-list\"><li>Keine Löschung oder Umbenennung bestehender <code>DataElement</code>s, <code>Operation</code>s oder Argumente.\n</li><li>Keine Änderung primitiver Datentypen, physikalischer Einheiten (CompuMethods) oder numerischer Skalierungsfaktoren.\n</li><li>Erweiterungen sind strikt additiv (z. B. neue optionale Record-Elemente, zusätzliche Fehlercodes).\n</li></ul>\n</li></ul>\n</li><li><strong>Auswirkungen auf Konfiguration und Tooling (ARXML &amp; RTE):</strong>\n<ul class=\"fig-list\"><li>Der RTE-Generator muss ARXML-Beschreibungen aus unterschiedlichen Release-Quellen auflösen können, ohne Typkollisionen bei systemweiten Standardtypen (z. B. <code>Std_ReturnType</code>, standardisierte Enums) zu erzeugen.\n</li><li>Integratoren müssen bei der Erstellung des <code>SystemExtract</code> sicherstellen, dass Port-Mappings zwischen SWCs verschiedener Releasestände formal typkompatibel deklariert sind.\n</li></ul>\n</li><li><strong>Entwicklungs- und Integrationspraxis:</strong>\n<ul class=\"fig-list\"><li><strong>Carry-over-Fähigkeit:</strong> Bereits abgenommene und qualifizierte Legacy-SWCs können ohne Quellcode- oder Schnittstellenanpassung in neuere Plattform-Projekte übernommen werden.\n</li><li><strong>Vermeidung von Re-Testing:</strong> Für unveränderte SWCs (R4.0.3) entfällt der Schnittstellen-Requalifizierungsaufwand; Tests können sich auf die geänderten Schnittstellenpfade der aktualisierten SWCs (R4.0.4) fokussieren.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f2551766ba5afb50", "releases": ["R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Konzeptionelles Architektur- und Migrationsdiagramm auf Basis des AUTOSAR Classic Platform (CP) Schichtenmodells.\n</li><li><strong>Technischer Zweck:</strong> Veranschaulichung der Rückwärtskompatibilität (<em>Backward Compatibility</em>, BWC) standardisierter AUTOSAR-Applikationsschnittstellen (<em>Standardized Application Interfaces</em>). Es demonstriert die Koexistenz von Software-Komponenten (SWCs) unterschiedlicher Spezifikationsstände (R4.0.3 und R4.0.4) auf demselben Steuergerät (ECU) und derselben Basissoftware (BSW/RTE), ohne dass alle SWCs simultan hochgezogen oder refaktoriert werden müssen.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Ausführungsumgebung &amp; Schichten (ECU Core):</strong>\n<ul class=\"fig-list\"><li><code>Microcontroller</code>: Physikalische Hardware-Ebene.\n</li><li><code>Microcontroller Abstraction Layer (MCAL)</code>: Hardware-nahe Treiberschicht (z. B. Port, ADC, DIO, CAN).\n</li><li><code>ECU Abstraction Layer</code>: Abstraktion interner/externer Peripherie- und Transceiverbausteine.\n</li><li><code>Services Layer</code>: BSW-Basisdienste (System-, Speicher- und Kommunikationsstack inkl. ComM, EcuM, NvM, Dem, Det).\n</li><li><code>Complex Device Drivers (CDD)</code>: Bypass-Schicht zur Direktanbindung zeitkritischer oder nicht standardisierter Hardware an die RTE/Applikation.\n</li><li><code>Runtime Environment (RTE)</code>: Virtual Functional Bus (VFB) Instanziierung zur Entkopplung von Applikation und BSW sowie SWC-zu-SWC-Vermittlung.\n</li></ul>\n</li><li><strong>Applikationsschicht (SWC-Entitäten):</strong>\n<ul class=\"fig-list\"><li>Heterogene Menge von <code>ApplicationSwComponentType</code>-Instanzen: SWC_1, SWC_2, SWC_3, …, SWC_n-1, SWC_n.\n</li><li><strong>Versionsspezifische Ausprägung:</strong>\n<ul class=\"fig-list\"><li><em>Graue SWCs:</em> Verwenden standardisierte Schnittstellen gemäß Stand <strong>R4.0.3</strong>.\n</li><li><em>Orangefarbene SWCs:</em> Verwenden standardisierte Schnittstellen gemäß Stand <strong>R4.0.4</strong>.\n</li></ul>\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Kopplung:</strong>\n<ul class=\"fig-list\"><li>Port-basierte Kommunikation über <code>PortPrototype</code> (<code>PPortPrototype</code>, <code>RPortPrototype</code>, <code>PRPortPrototype</code>).\n</li><li>Die BWC-Beziehung (dargestellt durch den Transformationspfeil <code>BWC wrt std app if</code>) garantiert, dass die Schnittstellen-Verträge von R4.0.4 kompatible Obermengen oder semantisch identische Abbildungen von R4.0.3 sind, wodurch <code>AssemblySwConnector</code>-Verbindungen zwischen Komponenten unterschiedlicher Releasestände gültig bleiben.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Migrations-/Evolutionsszenario (Statischer Systemzustand):</strong>\n<ul class=\"fig-list\"><li><em>Basiszustand (links):</em> Homogene Applikationsschicht; sämtliche Komponenten (SWC_1 bis SWC_n) basieren vollständig auf Schnittstellendefinitionen von R4.0.3.\n</li><li><em>Transitionszustand (rechts):</em> Inkrementelles Update einzelner Komponenten (SWC_2 und SWC_n-1) auf R4.0.4. Unveränderte Legacy-Komponenten (SWC_1, SWC_3, SWC_n) verbleiben auf R4.0.3-Standard-Interfaces.\n</li></ul>\n</li><li><strong>Laufzeitinteraktion:</strong>\n<ul class=\"fig-list\"><li>Datenaustausch (<code>Rte_Read</code>, <code>Rte_Write</code>) und Client/Server-Aufrufe (<code>Rte_Call</code>, <code>Rte_Result</code>) zwischen R4.0.3- und R4.0.4-SWCs werden transparent über den RTE-Code aufgelöst.\n</li><li>Es existieren keine dynamischen Fallbacks oder Laufzeit-Adapter; die Kompatibilität wird design- und generierungszeitlich durch identische Datentyplayouts, Skalierungen und Aufrufkonventionen sichergestellt.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative BWC-Vorgaben für Application Interfaces:</strong>\n<ul class=\"fig-list\"><li>Minor-/Bugfix-Releases standardisierter Applikationsschnittstellen (hier: R4.0.3 → R4.0.4) dürfen <strong>keine Breaking Changes</strong> enthalten:\n<ul class=\"fig-list\"><li>Keine Löschung oder Umbenennung bestehender <code>DataElement</code>s, <code>Operation</code>s oder Argumente.\n</li><li>Keine Änderung primitiver Datentypen, physikalischer Einheiten (CompuMethods) oder numerischer Skalierungsfaktoren.\n</li><li>Erweiterungen sind strikt additiv (z. B. neue optionale Record-Elemente, zusätzliche Fehlercodes).\n</li></ul>\n</li></ul>\n</li><li><strong>Auswirkungen auf Konfiguration und Tooling (ARXML &amp; RTE):</strong>\n<ul class=\"fig-list\"><li>Der RTE-Generator muss ARXML-Beschreibungen aus unterschiedlichen Release-Quellen auflösen können, ohne Typkollisionen bei systemweiten Standardtypen (z. B. <code>Std_ReturnType</code>, standardisierte Enums) zu erzeugen.\n</li><li>Integratoren müssen bei der Erstellung des <code>SystemExtract</code> sicherstellen, dass Port-Mappings zwischen SWCs verschiedener Releasestände formal typkompatibel deklariert sind.\n</li></ul>\n</li><li><strong>Entwicklungs- und Integrationspraxis:</strong>\n<ul class=\"fig-list\"><li><strong>Carry-over-Fähigkeit:</strong> Bereits abgenommene und qualifizierte Legacy-SWCs können ohne Quellcode- oder Schnittstellenanpassung in neuere Plattform-Projekte übernommen werden.\n</li><li><strong>Vermeidung von Re-Testing:</strong> Für unveränderte SWCs (R4.0.3) entfällt der Schnittstellen-Requalifizierungsaufwand; Tests können sich auf die geänderten Schnittstellenpfade der aktualisierten SWCs (R4.0.4) fokussieren.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-8abb79564ff955aa", "releases": ["R23-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Konzeptionelles Architektur- und Migrationsdiagramm auf Basis des AUTOSAR Classic Platform (CP) Schichtenmodells.\n</li><li><strong>Technischer Zweck:</strong> Veranschaulichung der Rückwärtskompatibilität (<em>Backward Compatibility</em>, BWC) standardisierter AUTOSAR-Applikationsschnittstellen (<em>Standardized Application Interfaces</em>). Es demonstriert die Koexistenz von Software-Komponenten (SWCs) unterschiedlicher Spezifikationsstände (R4.0.3 und R4.0.4) auf demselben Steuergerät (ECU) und derselben Basissoftware (BSW/RTE), ohne dass alle SWCs simultan hochgezogen oder refaktoriert werden müssen.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Ausführungsumgebung &amp; Schichten (ECU Core):</strong>\n<ul class=\"fig-list\"><li><code>Microcontroller</code>: Physikalische Hardware-Ebene.\n</li><li><code>Microcontroller Abstraction Layer (MCAL)</code>: Hardware-nahe Treiberschicht (z. B. Port, ADC, DIO, CAN).\n</li><li><code>ECU Abstraction Layer</code>: Abstraktion interner/externer Peripherie- und Transceiverbausteine.\n</li><li><code>Services Layer</code>: BSW-Basisdienste (System-, Speicher- und Kommunikationsstack inkl. ComM, EcuM, NvM, Dem, Det).\n</li><li><code>Complex Device Drivers (CDD)</code>: Bypass-Schicht zur Direktanbindung zeitkritischer oder nicht standardisierter Hardware an die RTE/Applikation.\n</li><li><code>Runtime Environment (RTE)</code>: Virtual Functional Bus (VFB) Instanziierung zur Entkopplung von Applikation und BSW sowie SWC-zu-SWC-Vermittlung.\n</li></ul>\n</li><li><strong>Applikationsschicht (SWC-Entitäten):</strong>\n<ul class=\"fig-list\"><li>Heterogene Menge von <code>ApplicationSwComponentType</code>-Instanzen: SWC_1, SWC_2, SWC_3, …, SWC_n-1, SWC_n.\n</li><li><strong>Versionsspezifische Ausprägung:</strong>\n<ul class=\"fig-list\"><li><em>Graue SWCs:</em> Verwenden standardisierte Schnittstellen gemäß Stand <strong>R4.0.3</strong>.\n</li><li><em>Orangefarbene SWCs:</em> Verwenden standardisierte Schnittstellen gemäß Stand <strong>R4.0.4</strong>.\n</li></ul>\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Kopplung:</strong>\n<ul class=\"fig-list\"><li>Port-basierte Kommunikation über <code>PortPrototype</code> (<code>PPortPrototype</code>, <code>RPortPrototype</code>, <code>PRPortPrototype</code>).\n</li><li>Die BWC-Beziehung (dargestellt durch den Transformationspfeil <code>BWC wrt std app if</code>) garantiert, dass die Schnittstellen-Verträge von R4.0.4 kompatible Obermengen oder semantisch identische Abbildungen von R4.0.3 sind, wodurch <code>AssemblySwConnector</code>-Verbindungen zwischen Komponenten unterschiedlicher Releasestände gültig bleiben.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Migrations-/Evolutionsszenario (Statischer Systemzustand):</strong>\n<ul class=\"fig-list\"><li><em>Basiszustand (links):</em> Homogene Applikationsschicht; sämtliche Komponenten (SWC_1 bis SWC_n) basieren vollständig auf Schnittstellendefinitionen von R4.0.3.\n</li><li><em>Transitionszustand (rechts):</em> Inkrementelles Update einzelner Komponenten (SWC_2 und SWC_n-1) auf R4.0.4. Unveränderte Legacy-Komponenten (SWC_1, SWC_3, SWC_n) verbleiben auf R4.0.3-Standard-Interfaces.\n</li></ul>\n</li><li><strong>Laufzeitinteraktion:</strong>\n<ul class=\"fig-list\"><li>Datenaustausch (<code>Rte_Read</code>, <code>Rte_Write</code>) und Client/Server-Aufrufe (<code>Rte_Call</code>, <code>Rte_Result</code>) zwischen R4.0.3- und R4.0.4-SWCs werden transparent über den RTE-Code aufgelöst.\n</li><li>Es existieren keine dynamischen Fallbacks oder Laufzeit-Adapter; die Kompatibilität wird design- und generierungszeitlich durch identische Datentyplayouts, Skalierungen und Aufrufkonventionen sichergestellt.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative BWC-Vorgaben für Application Interfaces:</strong>\n<ul class=\"fig-list\"><li>Minor-/Bugfix-Releases standardisierter Applikationsschnittstellen (hier: R4.0.3 → R4.0.4) dürfen <strong>keine Breaking Changes</strong> enthalten:\n<ul class=\"fig-list\"><li>Keine Löschung oder Umbenennung bestehender <code>DataElement</code>s, <code>Operation</code>s oder Argumente.\n</li><li>Keine Änderung primitiver Datentypen, physikalischer Einheiten (CompuMethods) oder numerischer Skalierungsfaktoren.\n</li><li>Erweiterungen sind strikt additiv (z. B. neue optionale Record-Elemente, zusätzliche Fehlercodes).\n</li></ul>\n</li></ul>\n</li><li><strong>Auswirkungen auf Konfiguration und Tooling (ARXML &amp; RTE):</strong>\n<ul class=\"fig-list\"><li>Der RTE-Generator muss ARXML-Beschreibungen aus unterschiedlichen Release-Quellen auflösen können, ohne Typkollisionen bei systemweiten Standardtypen (z. B. <code>Std_ReturnType</code>, standardisierte Enums) zu erzeugen.\n</li><li>Integratoren müssen bei der Erstellung des <code>SystemExtract</code> sicherstellen, dass Port-Mappings zwischen SWCs verschiedener Releasestände formal typkompatibel deklariert sind.\n</li></ul>\n</li><li><strong>Entwicklungs- und Integrationspraxis:</strong>\n<ul class=\"fig-list\"><li><strong>Carry-over-Fähigkeit:</strong> Bereits abgenommene und qualifizierte Legacy-SWCs können ohne Quellcode- oder Schnittstellenanpassung in neuere Plattform-Projekte übernommen werden.\n</li><li><strong>Vermeidung von Re-Testing:</strong> Für unveränderte SWCs (R4.0.3) entfällt der Schnittstellen-Requalifizierungsaufwand; Tests können sich auf die geänderten Schnittstellenpfade der aktualisierten SWCs (R4.0.4) fokussieren.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-ab94013ffaab47d7", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> Konzeptionelles Architektur- und Migrationsdiagramm auf Basis des AUTOSAR Classic Platform (CP) Schichtenmodells.\n</li><li><strong>Technischer Zweck:</strong> Veranschaulichung der Rückwärtskompatibilität (<em>Backward Compatibility</em>, BWC) standardisierter AUTOSAR-Applikationsschnittstellen (<em>Standardized Application Interfaces</em>). Es demonstriert die Koexistenz von Software-Komponenten (SWCs) unterschiedlicher Spezifikationsstände (R4.0.3 und R4.0.4) auf demselben Steuergerät (ECU) und derselben Basissoftware (BSW/RTE), ohne dass alle SWCs simultan hochgezogen oder refaktoriert werden müssen.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Ausführungsumgebung &amp; Schichten (ECU Core):</strong>\n<ul class=\"fig-list\"><li><code>Microcontroller</code>: Physikalische Hardware-Ebene.\n</li><li><code>Microcontroller Abstraction Layer (MCAL)</code>: Hardware-nahe Treiberschicht (z. B. Port, ADC, DIO, CAN).\n</li><li><code>ECU Abstraction Layer</code>: Abstraktion interner/externer Peripherie- und Transceiverbausteine.\n</li><li><code>Services Layer</code>: BSW-Basisdienste (System-, Speicher- und Kommunikationsstack inkl. ComM, EcuM, NvM, Dem, Det).\n</li><li><code>Complex Device Drivers (CDD)</code>: Bypass-Schicht zur Direktanbindung zeitkritischer oder nicht standardisierter Hardware an die RTE/Applikation.\n</li><li><code>Runtime Environment (RTE)</code>: Virtual Functional Bus (VFB) Instanziierung zur Entkopplung von Applikation und BSW sowie SWC-zu-SWC-Vermittlung.\n</li></ul>\n</li><li><strong>Applikationsschicht (SWC-Entitäten):</strong>\n<ul class=\"fig-list\"><li>Heterogene Menge von <code>ApplicationSwComponentType</code>-Instanzen: SWC_1, SWC_2, SWC_3, …, SWC_n-1, SWC_n.\n</li><li><strong>Versionsspezifische Ausprägung:</strong>\n<ul class=\"fig-list\"><li><em>Graue SWCs:</em> Verwenden standardisierte Schnittstellen gemäß Stand <strong>R4.0.3</strong>.\n</li><li><em>Orangefarbene SWCs:</em> Verwenden standardisierte Schnittstellen gemäß Stand <strong>R4.0.4</strong>.\n</li></ul>\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Kopplung:</strong>\n<ul class=\"fig-list\"><li>Port-basierte Kommunikation über <code>PortPrototype</code> (<code>PPortPrototype</code>, <code>RPortPrototype</code>, <code>PRPortPrototype</code>).\n</li><li>Die BWC-Beziehung (dargestellt durch den Transformationspfeil <code>BWC wrt std app if</code>) garantiert, dass die Schnittstellen-Verträge von R4.0.4 kompatible Obermengen oder semantisch identische Abbildungen von R4.0.3 sind, wodurch <code>AssemblySwConnector</code>-Verbindungen zwischen Komponenten unterschiedlicher Releasestände gültig bleiben.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Migrations-/Evolutionsszenario (Statischer Systemzustand):</strong>\n<ul class=\"fig-list\"><li><em>Basiszustand (links):</em> Homogene Applikationsschicht; sämtliche Komponenten (SWC_1 bis SWC_n) basieren vollständig auf Schnittstellendefinitionen von R4.0.3.\n</li><li><em>Transitionszustand (rechts):</em> Inkrementelles Update einzelner Komponenten (SWC_2 und SWC_n-1) auf R4.0.4. Unveränderte Legacy-Komponenten (SWC_1, SWC_3, SWC_n) verbleiben auf R4.0.3-Standard-Interfaces.\n</li></ul>\n</li><li><strong>Laufzeitinteraktion:</strong>\n<ul class=\"fig-list\"><li>Datenaustausch (<code>Rte_Read</code>, <code>Rte_Write</code>) und Client/Server-Aufrufe (<code>Rte_Call</code>, <code>Rte_Result</code>) zwischen R4.0.3- und R4.0.4-SWCs werden transparent über den RTE-Code aufgelöst.\n</li><li>Es existieren keine dynamischen Fallbacks oder Laufzeit-Adapter; die Kompatibilität wird design- und generierungszeitlich durch identische Datentyplayouts, Skalierungen und Aufrufkonventionen sichergestellt.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative BWC-Vorgaben für Application Interfaces:</strong>\n<ul class=\"fig-list\"><li>Minor-/Bugfix-Releases standardisierter Applikationsschnittstellen (hier: R4.0.3 → R4.0.4) dürfen <strong>keine Breaking Changes</strong> enthalten:\n<ul class=\"fig-list\"><li>Keine Löschung oder Umbenennung bestehender <code>DataElement</code>s, <code>Operation</code>s oder Argumente.\n</li><li>Keine Änderung primitiver Datentypen, physikalischer Einheiten (CompuMethods) oder numerischer Skalierungsfaktoren.\n</li><li>Erweiterungen sind strikt additiv (z. B. neue optionale Record-Elemente, zusätzliche Fehlercodes).\n</li></ul>\n</li></ul>\n</li><li><strong>Auswirkungen auf Konfiguration und Tooling (ARXML &amp; RTE):</strong>\n<ul class=\"fig-list\"><li>Der RTE-Generator muss ARXML-Beschreibungen aus unterschiedlichen Release-Quellen auflösen können, ohne Typkollisionen bei systemweiten Standardtypen (z. B. <code>Std_ReturnType</code>, standardisierte Enums) zu erzeugen.\n</li><li>Integratoren müssen bei der Erstellung des <code>SystemExtract</code> sicherstellen, dass Port-Mappings zwischen SWCs verschiedener Releasestände formal typkompatibel deklariert sind.\n</li></ul>\n</li><li><strong>Entwicklungs- und Integrationspraxis:</strong>\n<ul class=\"fig-list\"><li><strong>Carry-over-Fähigkeit:</strong> Bereits abgenommene und qualifizierte Legacy-SWCs können ohne Quellcode- oder Schnittstellenanpassung in neuere Plattform-Projekte übernommen werden.\n</li><li><strong>Vermeidung von Re-Testing:</strong> Für unveränderte SWCs (R4.0.3) entfällt der Schnittstellen-Requalifizierungsaufwand; Tests können sich auf die geänderten Schnittstellenpfade der aktualisierten SWCs (R4.0.4) fokussieren.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-64499dfb95518e75", "to": "FIG-e8c38bcc09bf7986", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-e8c38bcc09bf7986", "to": "FIG-f2551766ba5afb50", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-f2551766ba5afb50", "to": "FIG-8abb79564ff955aa", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-8abb79564ff955aa", "to": "FIG-ab94013ffaab47d7", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
